Translate("frFR", "ragefire-chasm", {
	title = "Gouffre de Ragefeu",
	aliases = { "Ragefeu" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Gouffre de Ragefeu est un réseau de cavernes ardentes sous {link:orgrimmar}Orgrimmar{/link}. Des rivières de lave éclairent ses tunnels, et la chaleur des profondeurs monte à travers sa pierre. On l'atteint par un passage au fond de la {link:cleft-of-shadow}Cleft of Shadow{/link}. Peu de citoyens de la capitale savent ce qui se trouve sous leurs pieds. Ceux qui le savent ont des raisons de le craindre, car le gouffre abrite des troggs sauvages et un culte secret qui complote la chute de la {link:horde}Horde{/link}.]=],
		},
		{
			title = "Origines",
			text = [=[Aucune chronique ne dit qui découvrit le gouffre le premier, ni jusqu'où descendent ses tunnels. Les troggs vinrent d'abord. Ils montèrent des profondeurs emplies de lave et firent leurs les cavernes supérieures. Puis la Searing Blade descendit de la cité au-dessus, une secte du {link:shadow-council}Conseil des ombres{/link} et une sœur de la {link:burning-blade}Lame ardente{/link}. Les troggs étaient trop faibles pour la chasser, et les deux partagent désormais les ténèbres dans une hostilité inquiète.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[La Searing Blade a fait du gouffre son sanctuaire. Ses cultistes se croient la génération montante de l'art des démonistes, et ils s'efforcent de convertir le peuple loyal d'{link:orgrimmar}Orgrimmar{/link} au culte des démons. Trois chefs les commandent : un gangregarde, {link:taragaman-the-hungerer}Taragaman l'Affamé{/link}, un démoniste, {link:jergosh-the-invoker}Jergosh l'Invocateur{/link}, et un {link:satyrs}satyre{/link}, {link:bazzalan}Bazzalan{/link}. Les troggs du clan Ragefeu tiennent encore les cavernes proches de l'entrée sous leur chef, {link:oggleflint}Oggleflint{/link}.

Le gouffre attire les regards de toute la {link:horde}Horde{/link}. La voyante {link:tauren}tauren{/link} {link:magatha-grimtotem}Magatha Grimtotem{/link} envoya des émissaires faire la paix avec les troggs, et ils furent massacrés. L'un de ses serviteurs, {link:maur-raincaller}Maur{/link} Grimtotem, descendit leur parler et ne revint jamais. Des émissaires des {link:forsaken}Réprouvés{/link} veulent deux livres de sorts ténébreux que détiennent les cultistes. Par-dessus tout, le chef de guerre {link:thrall}Thrall{/link} observe. Le démoniste {link:neeru-fireblade}Neeru Fireblade{/link} envoie des héros dans le gouffre, et Thrall sait exactement pourquoi.]=],
		},
		{
			title = "Dans le gouffre",
			text = [=[• {b}Les cavernes des troggs.{/b} Près de l'entrée, les troggs du clan Ragefeu livrent leur dernier combat. {link:oggleflint}Oggleflint{/link} règne sur eux.
• {b}Les bassins de lave.{/b} Plus loin, les tunnels s'ouvrent sur des lacs de roche en fusion, où des élémentaires de magma flottent au-dessus du feu et où de grands foreurs creusent la pierre. Les cultistes montent la garde parmi eux.
• {b}La plate-forme de l'Affamé.{/b} {link:taragaman-the-hungerer}Taragaman l'Affamé{/link} attend au-dessus du feu, le chef que le culte montre au monde.
• {b}La chambre du démoniste.{/b} {link:jergosh-the-invoker}Jergosh l'Invocateur{/link} accomplit ses rites dans une chambre des cavernes inférieures.
• {b}La corniche du {link:satyrs}satyre{/link}.{/b} Au-dessus de la chambre du démoniste, sur une corniche que l'on atteint par de sombres rampes, {link:bazzalan}Bazzalan{/link} attend dans l'ombre.]=],
		},
		{
			title = "Ceux qui vivent en bas",
			text = [=[La Searing Blade se divise en cultistes, en exécuteurs et en démonistes, chacun plus dangereux que le précédent. Le corps de {link:maur-raincaller}Maur{/link} Grimtotem gît quelque part dans les tunnels, serrant encore une besace qu'il ne voulait pas lâcher. La plupart des cultistes ignorent la vérité : leurs vrais maîtres, là-haut, ne les voient que comme des pions sacrifiables, et seuls deux de leurs chefs ont du prix à leurs yeux.]=],
		},
	},
})

Translate("frFR", "taragaman-the-hungerer", {
	title = "Taragaman l'Affamé",
	subtitle = "Gangregarde de la Searing Blade",
	found = [=[Une plate-forme au-dessus de la lave, au fond du Gouffre de Ragefeu]=],
	hint = [=[Affrontez le gangregarde qui règne sur les profondeurs du Gouffre de Ragefeu.]=],
	allegiance = "Searing Blade · Légion ardente",
	aliases = { "Taragaman" },
	sections = {
		{
			title = "Résumé",
			text = [=[Taragaman l'Affamé est un gangregarde, un guerrier démoniaque de la {link:burning-legion}Légion ardente{/link}, qui demeure dans les profondeurs du {link:ragefire-chasm}Gouffre de Ragefeu{/link}. Pour les cultistes de la Searing Blade, il est leur maître, et pour les rares habitants d'{link:orgrimmar}Orgrimmar{/link} qui connaissent le gouffre, il est le chef de la secte. Depuis sa plate-forme au-dessus du feu, il répand l'influence de la Légion parmi les citoyens de la cité au-dessus. Peu de ceux qui sont descendus l'affronter sont revenus.]=],
		},
		{
			title = "Importance",
			text = [=[Taragaman est le visage de la Searing Blade. Il est aussi son plus grand mensonge. Ceux qui commandent vraiment le culte en ont fait un appât, un démon assez imposant pour attirer les loyaux serviteurs du chef de guerre dans les ténèbres, pour qu'ils y meurent.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il dirige la Searing Blade aux yeux de ses fidèles.
• Il s'efforce de corrompre le peuple d'{link:orgrimmar}Orgrimmar{/link} par l'influence démoniaque.
• Il attend dans les profondeurs ceux que l'on envoie le tuer.
• Il cache les vrais chefs de la secte derrière son propre nom redoutable.]=],
		},
	},
	chapters = {
		{
			title = "Abattre la bête",
			hint = "Apportez le cœur du gangregarde à Neeru Fireblade.",
			text = [=[{link:neeru-fireblade}Neeru Fireblade{/link} désigna Taragaman comme le chef de la Searing Blade et demanda son cœur, afin que le chef de guerre soit satisfait. Quand on lui apporta le cœur, il promit de s'en occuper comme il se doit et d'annoncer la victoire à {link:thrall}Thrall{/link}. Pourtant, Neeru n'avait rien sacrifié de ce qui lui importait. Le gangregarde n'était qu'un appât, un démon assez imposant pour attirer les fidèles de Thrall dans le gouffre. Les vrais chefs de la secte vivaient encore, et le démoniste espérait toujours les garder.]=],
		},
	},
	mentions = {
		{ text = "Abattre la bête" },
	},
	bonds = {
		{ id = "neeru-fireblade", name = "Neeru Fireblade", note = "envoya des héros le tuer" },
		{ id = "jergosh-the-invoker", name = "Jergosh l'Invocateur", note = "un chef de la même secte" },
		{ id = "bazzalan", name = "Bazzalan", note = "un chef de la même secte" },
	},
})

Translate("frFR", "jergosh-the-invoker", {
	title = "Jergosh l'Invocateur",
	subtitle = "Démoniste de la Searing Blade",
	found = "Une chambre des cavernes inférieures du Gouffre de Ragefeu",
	hint = [=[Affrontez le démoniste orc qui dirige la Searing Blade dans les profondeurs du Gouffre de Ragefeu.]=],
	allegiance = "Searing Blade · Conseil des ombres",
	aliases = { "Jergosh" },
	sections = {
		{
			title = "Résumé",
			text = [=[Jergosh l'Invocateur est un démoniste {link:orcs}orc{/link} qui rejeta les nouvelles voies de son peuple et se tourna vers les démons que celui-ci avait rejetés. Il est l'un des vrais chefs de la Searing Blade, et les cultistes des cavernes inférieures obéissent à chacune de ses paroles. Ses machinations sous {link:orgrimmar}Orgrimmar{/link} sont devenues assez dangereuses pour attirer l'attention du chef de guerre lui-même.]=],
		},
		{
			title = "Importance",
			text = [=[Jergosh est précieux aux yeux des maîtres du culte. C'est pour cette raison que {link:thrall}Thrall{/link} veut sa mort.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il dirige la Searing Blade dans le {link:ragefire-chasm}Gouffre de Ragefeu{/link} aux côtés du {link:satyrs}satyre{/link} {link:bazzalan}Bazzalan{/link}.
• Il accomplit ses rites ténébreux dans les cavernes inférieures.]=],
		},
	},
	mentions = {
		{ text = "Ennemis cachés" },
	},
	bonds = {
		{ id = "bazzalan", name = "Bazzalan", note = "dirige la secte à ses côtés" },
		{ id = "neeru-fireblade", name = "Neeru Fireblade", note = "tient à lui" },
		{ id = "thrall", name = "Thrall", note = "ordonna sa mort" },
	},
})

Translate("frFR", "bazzalan", {
	title = "Bazzalan",
	subtitle = "Satyre de la Searing Blade",
	found = [=[Une corniche au-dessus de la chambre du démoniste, dans le Gouffre de Ragefeu]=],
	hint = [=[Fouillez les sombres corniches du Gouffre de Ragefeu à la recherche d'un satyre.]=],
	allegiance = "Searing Blade · Conseil des ombres",
	sections = {
		{
			title = "Résumé",
			text = [=[Bazzalan est un {link:satyrs}satyre{/link}, l'un des êtres déformés par les démons de l'antique {link:kalimdor}Kalimdor{/link}, qui rôde sur les corniches supérieures du {link:ragefire-chasm}Gouffre de Ragefeu{/link}. Il est rapide, rusé et mortel avec une lame. Ses desseins n'appartiennent qu'à lui. Pourtant, lui et le démoniste {link:jergosh-the-invoker}Jergosh{/link} sont les vrais chefs de la Searing Blade, et les maîtres du culte l'estiment plus que le gangregarde qui se tient à sa place.]=],
		},
		{
			title = "Importance",
			text = [=[Bazzalan est l'une des deux têtes cachées de la Searing Blade. Sa mort est un coup que le culte ne peut dissimuler.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il dirige la Searing Blade dans le {link:ragefire-chasm}Gouffre de Ragefeu{/link} aux côtés de {link:jergosh-the-invoker}Jergosh l'Invocateur{/link}.
• Il se tient dans l'ombre, bien au-dessus des cavernes inférieures.]=],
		},
	},
	mentions = {
		{ text = "Ennemis cachés" },
	},
	bonds = {
		{ id = "jergosh-the-invoker", name = "Jergosh l'Invocateur", note = "dirige la secte à ses côtés" },
		{ id = "neeru-fireblade", name = "Neeru Fireblade", note = "tient à lui" },
	},
})

Translate("frFR", "oggleflint", {
	title = "Oggleflint",
	subtitle = "Chef des Ragefeu",
	found = [=[Les cavernes des troggs près de l'entrée du Gouffre de Ragefeu]=],
	hint = [=[Affrontez le chef des troggs qui gardent l'entrée du Gouffre de Ragefeu.]=],
	allegiance = "Troggs Ragefeu",
	sections = {
		{
			title = "Résumé",
			text = [=[Oggleflint est le chef des troggs {link:ragefire-chasm}Ragefeu{/link}, des créatures brutales qui sortirent des tunnels de lave sous {link:orgrimmar}Orgrimmar{/link}. Son peuple régnait autrefois seul sur le gouffre. Quand la Searing Blade arriva, les troggs ne purent la chasser, et ils se replièrent dans les cavernes proches de l'entrée. Là, ils attendent que les intrus s'en aillent.]=],
		},
		{
			title = "Importance",
			text = [=[Les troggs d'Oggleflint sont une menace pour toute la {link:horde}Horde{/link}. Ils tuèrent les émissaires que {link:magatha-grimtotem}Magatha Grimtotem{/link} avait envoyés pour faire la paix, et ils envahiraient la cité par en dessous s'ils le pouvaient.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il dirige les troggs du {link:ragefire-chasm}Gouffre de Ragefeu{/link}.
• Son peuple massacra les émissaires taurens envoyés pour traiter avec lui.]=],
		},
	},
	mentions = {
		{ text = "Mettre à l'épreuve la force de l'ennemi" },
	},
})
